_NONCE_SIZE = 12

_K_PARTS = [250, 69, 159, 145, 130, 124, 213, 207, 68, 171, 92, 167, 120, 248, 248, 18, 182, 169, 140, 215, 171, 22, 84, 186, 208, 29, 70, 53, 2, 102, 53, 91]
_K_MASK = [152, 167, 217, 207, 92, 44, 246, 28, 33, 198, 208, 115, 254, 44, 155, 145, 80, 173, 245, 92, 195, 12, 107, 126, 52, 142, 217, 113, 104, 108, 16, 181]

def _rebuild_key():
    parts = _K_PARTS
    mask = _K_MASK
    key = bytes(p ^ m for p, m in zip(parts, mask))
    return key

def _run():
    raw = base64.b85decode(_PAYLOAD)
    nonce, ciphertext = raw[:_NONCE_SIZE], raw[_NONCE_SIZE:]
    key = _rebuild_key()
    aesgcm = AESGCM(key)
    try:
        compressed = aesgcm.decrypt(nonce, ciphertext, None)
    except Exception:
        sys.stderr.write("Corrupted or tampered protected file.\n")
        sys.exit(1)
    raw_bytecode = zlib.decompress(compressed)
    code_obj = marshal.loads(raw_bytecode)
    exec(code_obj, {"__name__": "__main__"})

_run()
